-- App Finanzas: esquema de negocio PostgreSQL.
-- npm run migrate aplica este archivo y sessions.sql en una base vacía.

--
-- Create model User
--
CREATE TABLE "usuarios" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "username" varchar(150) NOT NULL UNIQUE,
    "email" varchar(254) NOT NULL UNIQUE,
    "password" varchar(128) NOT NULL,
    "nombre" varchar(150) NOT NULL,
    "telefono" varchar(30) NOT NULL,
    "is_active" boolean NOT NULL,
    "date_joined" timestamp with time zone NOT NULL,
    "last_login" timestamp with time zone NULL,
    "cash_balance" numeric(18, 2) NOT NULL,
    "notifications" boolean NOT NULL,
    "dark_mode" boolean NOT NULL
);
--
-- Create model Stock
--
CREATE TABLE "acciones" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "symbol" varchar(12) NOT NULL UNIQUE, "nombre" varchar(100) NOT NULL, "sector" varchar(80) NOT NULL, "precio" numeric(18, 2) NOT NULL, "cambio_porcentual" numeric(7, 2) NOT NULL, "color" varchar(7) NOT NULL, "fecha_actualizacion" timestamp with time zone NOT NULL, CONSTRAINT "acciones_positive_price" CHECK ("precio" > 0));
--
-- Create model Holding
--
CREATE TABLE "portafolio" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "quantity" numeric(18, 6) NOT NULL, "invested" numeric(18, 2) NOT NULL, "usuario_id" bigint NOT NULL, "accion_id" bigint NOT NULL);
--
-- Create model Transaction
--
CREATE TABLE "transacciones" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "tipo" varchar(7) NOT NULL, "descripcion" varchar(255) NOT NULL, "cantidad" numeric(18, 6) NOT NULL, "precio_unitario" numeric(18, 2) NOT NULL, "monto" numeric(18, 2) NOT NULL, "fecha" timestamp with time zone NOT NULL, "accion_id" bigint NULL, "usuario_id" bigint NOT NULL);
--
-- Create constraint usuarios_email_ci_unique on model user
--
CREATE UNIQUE INDEX "usuarios_email_ci_unique" ON "usuarios" ((LOWER("email")));
--
-- Create constraint usuarios_username_ci_unique on model user
--
CREATE UNIQUE INDEX "usuarios_username_ci_unique" ON "usuarios" ((LOWER("username")));
--
-- Create constraint usuarios_cash_nonnegative on model user
--
ALTER TABLE "usuarios" ADD CONSTRAINT "usuarios_cash_nonnegative" CHECK ("cash_balance" >= 0);
--
-- Create constraint portafolio_user_stock_unique on model holding
--
ALTER TABLE "portafolio" ADD CONSTRAINT "portafolio_user_stock_unique" UNIQUE ("usuario_id", "accion_id");
--
-- Create constraint portafolio_positive_quantity on model holding
--
ALTER TABLE "portafolio" ADD CONSTRAINT "portafolio_positive_quantity" CHECK ("quantity" > 0);
--
-- Create constraint portafolio_nonnegative_invested on model holding
--
ALTER TABLE "portafolio" ADD CONSTRAINT "portafolio_nonnegative_invested" CHECK ("invested" >= 0);
--
-- Create index trans_user_date_idx on field(s) usuario, -fecha of model transaction
--
CREATE INDEX "trans_user_date_idx" ON "transacciones" ("usuario_id", "fecha" DESC);
--
-- Create constraint transacciones_positive_amount on model transaction
--
ALTER TABLE "transacciones" ADD CONSTRAINT "transacciones_positive_amount" CHECK ("monto" > 0);
--
-- Create constraint transacciones_valid_type on model transaction
--
ALTER TABLE "transacciones" ADD CONSTRAINT "transacciones_valid_type" CHECK ("tipo" IN ('buy', 'sell', 'deposit'));
--
-- Create constraint transacciones_valid_shape on model transaction
--
ALTER TABLE "transacciones" ADD CONSTRAINT "transacciones_valid_shape" CHECK ((("accion_id" IS NULL AND "cantidad" = 0 AND "precio_unitario" = 0 AND "tipo" = 'deposit') OR ("accion_id" IS NOT NULL AND "cantidad" > 0 AND "precio_unitario" > 0 AND "tipo" IN ('buy', 'sell'))));
--
-- Create model PasswordResetChallenge
--
CREATE TABLE "password_reset_challenges" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "challenge_id" uuid NOT NULL UNIQUE, "email" varchar(254) NOT NULL, "password_fingerprint" varchar(64) NOT NULL, "code_digest" varchar(64) NOT NULL, "reset_token_digest" varchar(64) NOT NULL, "expires_at" timestamp with time zone NOT NULL, "verified_at" timestamp with time zone NULL, "consumed_at" timestamp with time zone NULL, "attempts" smallint NOT NULL CHECK ("attempts" >= 0), "sent_at" timestamp with time zone NOT NULL, "send_window_started_at" timestamp with time zone NOT NULL, "send_count" smallint NOT NULL CHECK ("send_count" >= 0), "user_id" bigint NOT NULL UNIQUE);
--
-- Create model LoginChallenge
--
CREATE TABLE "login_challenges" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "challenge_id" uuid NOT NULL UNIQUE, "email" varchar(254) NOT NULL, "password_fingerprint" varchar(64) NOT NULL, "browser_digest" varchar(64) NOT NULL, "code_digest" varchar(64) NOT NULL, "expires_at" timestamp with time zone NOT NULL, "consumed_at" timestamp with time zone NULL, "attempts" smallint NOT NULL CHECK ("attempts" >= 0), "sent_at" timestamp with time zone NOT NULL, "send_window_started_at" timestamp with time zone NOT NULL, "send_count" smallint NOT NULL CHECK ("send_count" >= 0), "user_id" bigint NOT NULL UNIQUE);
--
-- Create model PaymentCard
--
CREATE TABLE "payment_cards" ("id" uuid NOT NULL PRIMARY KEY, "request_id" uuid NOT NULL, "stripe_customer_id" varchar(255) NOT NULL, "stripe_setup_intent_id" varchar(255) NULL UNIQUE, "stripe_payment_method_id" varchar(255) NULL UNIQUE, "brand" varchar(30) NOT NULL, "last4" varchar(4) NOT NULL, "exp_month" smallint NULL CHECK ("exp_month" >= 0), "exp_year" smallint NULL CHECK ("exp_year" >= 0), "verified_at" timestamp with time zone NULL, "verified_email" varchar(254) NOT NULL, "disabled_at" timestamp with time zone NULL, "created_at" timestamp with time zone NOT NULL, "usuario_id" bigint NOT NULL);
--
-- Create model CardVerification
--
CREATE TABLE "card_verifications" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "challenge_id" uuid NOT NULL UNIQUE, "email" varchar(254) NOT NULL, "code_digest" varchar(64) NOT NULL, "expires_at" timestamp with time zone NOT NULL, "consumed_at" timestamp with time zone NULL, "attempts" smallint NOT NULL CHECK ("attempts" >= 0), "sent_at" timestamp with time zone NOT NULL, "send_window_started_at" timestamp with time zone NOT NULL, "send_count" smallint NOT NULL CHECK ("send_count" >= 0), "card_id" uuid NOT NULL UNIQUE);
--
-- Create model StripeCustomer
--
CREATE TABLE "stripe_customers" ("id" uuid NOT NULL PRIMARY KEY, "customer_id" varchar(255) NULL UNIQUE, "created_at" timestamp with time zone NOT NULL, "usuario_id" bigint NOT NULL UNIQUE);
--
-- Create model TopUp
--
CREATE TABLE "payment_topups" ("id" uuid NOT NULL PRIMARY KEY, "request_id" uuid NOT NULL, "amount" numeric(18, 2) NOT NULL, "currency" varchar(3) NOT NULL, "stripe_customer_id" varchar(255) NOT NULL, "stripe_payment_intent_id" varchar(255) NULL UNIQUE, "status" varchar(10) NOT NULL, "credited_at" timestamp with time zone NULL, "created_at" timestamp with time zone NOT NULL, "card_id" uuid NOT NULL, "transaction_id" bigint NULL UNIQUE, "usuario_id" bigint NOT NULL);
--
-- Create model PaymentEmailOutbox
--
CREATE TABLE "payment_email_outbox" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "recipient" varchar(254) NOT NULL, "sent_at" timestamp with time zone NULL, "attempts" integer NOT NULL CHECK ("attempts" >= 0), "last_attempt_at" timestamp with time zone NULL, "next_attempt_at" timestamp with time zone NOT NULL, "created_at" timestamp with time zone NOT NULL, "topup_id" uuid NOT NULL UNIQUE);
--
-- Create constraint card_user_request_unique on model paymentcard
--
ALTER TABLE "payment_cards" ADD CONSTRAINT "card_user_request_unique" UNIQUE ("usuario_id", "request_id");
--
-- Create constraint topup_user_request_unique on model topup
--
ALTER TABLE "payment_topups" ADD CONSTRAINT "topup_user_request_unique" UNIQUE ("usuario_id", "request_id");
--
-- Create constraint topup_positive_amount on model topup
--
ALTER TABLE "payment_topups" ADD CONSTRAINT "topup_positive_amount" CHECK ("amount" > 0);
--
-- Create constraint topup_currency_mxn on model topup
--
ALTER TABLE "payment_topups" ADD CONSTRAINT "topup_currency_mxn" CHECK ("currency" = 'mxn');
--
-- Create constraint topup_valid_status on model topup
--
ALTER TABLE "payment_topups" ADD CONSTRAINT "topup_valid_status" CHECK ("status" IN ('pending', 'succeeded', 'failed'));
--
-- Create constraint topup_credit_consistent on model topup
--
ALTER TABLE "payment_topups" ADD CONSTRAINT "topup_credit_consistent" CHECK ((("credited_at" IS NOT NULL AND "status" = 'succeeded' AND "transaction_id" IS NOT NULL) OR ("credited_at" IS NULL AND "status" IN ('pending', 'failed') AND "transaction_id" IS NULL)));
